986	+    /// returns each mismatch.
987	+    fn mismatches(name: &str, params: &Value) -> Vec<String> {
988	+        let Some((_, required, optional)) = TSRS_READS.iter().find(|(known, _, _)| *known == name) else {
989	+            return vec![format!("{name}: not in the table of what tsrs reads")];
990	+        };
991	+        let Some(object) = params.as_object() else {
992	+            return if required.is_empty() && params.is_null() { vec![] } else { vec![format!("{name}: {params}")] };
993	+        };
994	+        let mut wrong: Vec<String> = Vec::new();
995	+        for key in object.keys() {
996	+            if !required.contains(&key.as_str()) && !optional.contains(&key.as_str()) {
997	+                wrong.push(format!("{name}: sends `{key}`, which tsrs does not read"));
998	+            }
999	+        }
1000	+        for key in *required {
1001	+            if !object.contains_key(*key) {
1002	+                wrong.push(format!("{name}: does not send `{key}`"));
1003	+            }
1004	+        }
1005	+        let each = |value: &'_ Value, key: &str| value.get(key).and_then(Value::as_array).cloned().unwrap_or_default();
1006	+        // `createSnapshot` takes the changes as its parameters, `updateSnapshot` under `changes`.
1007	+        if let Some(changes) = object.get("changes") {
1008	+            wrong.extend(mismatches("CreateSnapshotParams", changes));
