1010	+        let changes = object.get("changes").unwrap_or(params);
1011	+        if let Some(notified) = changes.get("fileNotifications") {
1012	+            wrong.extend(mismatches("FileNotifications", notified));
1013	+        }
1014	+        for program in each(changes, "createPrograms") {
1015	+            wrong.extend(mismatches("CreateSnapshotProgramParams", &program));
1016	+        }
1017	+        for program in each(changes, "reconfigurePrograms") {
